/// <reference path="../../node_modules/@types/p5/global.d.ts" />
//this variable will hold our shader object

let myShader;

function preload() {
  // a shader is composed of two parts, a vertex shader, and a fragment shader
  // the vertex shader prepares the vertices and geometry to be drawn
  // the fragment shader renders the actual pixel colors
  // loadShader() is asynchronous so it needs to be in preload
  // loadShader() first takes the filename of a vertex shader, and then a frag shader
  // these file types are usually .vert and .frag, but you can actually use anything. .glsl is another common one
  myShader = loadShader("https://openprocessing.org/sketch/1165640/files/vert.txt", "frag.txt");
}

function setup() {
  // shaders require WEBGL mode to work
  createCanvas(1112, 834, WEBGL);
  noStroke();
}

function draw() {
  background(0);
  // shader() sets the active shader with our shader
  shader(myShader);

  // Send the frameCount to the shader
  myShader.setUniform("uFrameCount", frameCount*0.5);

  // Rotate our geometry on the X and Y axes
  rotateX(frameCount * 0.02);
  rotateY(frameCount * 0.01);

  // Draw some geometry to the screen
  // We're going to tessellate the sphere a bit so we have some more geometry to work with
  sphere(width / 4, 200, 200);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

